def max_value_on_paths(N, grid_values):
    grid = [[0] * N for _ in range(N)]
    dp = [[0] * N for _ in range(N)]
    for x, y, val in grid_values:
        grid[x][y] = val
    for i in range(N):
        for j in range(N):
            if i > 0 and j > 0:
                dp[i][j] = max(grid[i][j], dp[i - 1][j], dp[i][j - 1])
            elif i > 0:
                dp[i][j] = max(grid[i][j], dp[i - 1][j])
            elif j > 0:
                dp[i][j] = max(grid[i][j], dp[i][j - 1])
            else:
                dp[i][j] = grid[i][j]
    return dp[N - 1][N - 1]
