def max_value_on_paths(N, grid_values):
    # Initialize a 2D array to store the maximum sum of values collected on the two paths
    dp = [[0] * (N + 1) for _ in range(N + 1)]

    # Loop through the grid values and update the dp array
    for x, y, value in grid_values:
        dp[x][y] = value
        for i in range(x):
            dp[x][y] += dp[i][y]
        for j in range(y):
            dp[x][y] += dp[x][j]

    # Return the maximum sum of values collected on the two paths
    return max(dp[N - 1][y] for y in range(N))
