def cantor_numbering(N: int) -> str:
    """
    Determines the numerator and denominator of the N-th term in the Cantor table.

    Args:
        N (int): The position in the Cantor table to find the corresponding fraction for.

    Returns:
        str: A string representation of the fraction at the N-th position in the Cantor table.
    """
    def cantor_sequence(n):
        """Helper function to generate the Cantor sequence."""
        if n == 1:
            return 1
        elif n % 3 == 1:
            return 1 / cantor_sequence(n // 3)
        elif n % 3 == 2:
            return 2 / cantor_sequence(n // 3)
        else:
            return 1 / cantor_sequence(n // 3) + cantor_sequence(n // 3 + 1)

    num, den = 1, 1
    while cantor_sequence(den) < N:
        num, den = num + 1, den + 1

    return f"{num}/{den}"
```

