def max_product(num_str, N, K):
    if K == 0:
        return int(num_str)

    # Find the maximum product by inserting multiplication signs
    # in all possible positions between adjacent digits
    max_product = 1
    for i in range(N - 1):
        product = int(num_str[:i + 1]) * int(num_str[i + 1:])
        max_product = max(max_product, product)

    # Recursively call the function with one less multiplication sign
    return max(max_product, max_product(num_str, N, K - 1))
