def max_product(num_str, N, K):
    if K == 0:
        return int(num_str)

    nums = [int(num_str[i]) for i in range(N)]
    dp = [0] * (N + 1)

    for i in range(1, N + 1):
        dp[i] = max(dp[i - 1], dp[i - 2] * nums[i - 1])

    for i in range(K):
        for j in range(N, i, -1):
            dp[j] = max(dp[j], dp[j - 1] * nums[j])

    return dp[N]
```

