def count_passing_ways(n, m):
    # Initialize a 2D list to store the dynamic programming states
    dp = [[0] * (n + 1) for _ in range(m + 1)]

    # Base case: no student passes the ball
    for i in range(n + 1):
        dp[0][i] = 1

    # Fill the dynamic programming table
    for j in range(1, m + 1):
        for i in range(n + 1):
            if i == 0:
                dp[j][i] = dp[j - 1][n]
            elif i == n:
                dp[j][i] = dp[j - 1][0]
            else:
                dp[j][i] = dp[j - 1][i - 1] + dp[j - 1][i + 1]

    # Return the number of passing ways
    return dp[m][0]
